'VopSEEC0rIIuU8kzeNCmVI4BD5HcW143ZM3XnPliXgwb1/uRX1+wGfbHoUo4/y8Gor6CHyMAAA=='
    };
    gzH=matlab.net.base64decode([B64H{:}]);
    gzPathH=fullfile(stageDir,'af7r58zzt_process_worker.m.gz');
    fh=fopen(gzPathH,'wb'); assert(fh>=0);
    fwrite(fh,uint8(gzH),'uint8'); fclose(fh);
    gunzip(gzPathH,stageDir);
    stagedH=fullfile(stageDir,'af7r58zzt_process_worker.m');
    assert(strcmp(file_hash(stagedH),HELPER_SHA), ...
        '[AF7R58ZZT] staged worker helper SHA mismatch.');

    R=read_utf8(stagedR);
    H=read_utf8(stagedH);

    % Static safety/architecture audit before first production write.
    assert(count_exact(R,'horizon_s     = 4.0;')==1);
    assert(~contains(R,'prepare_early_intervention_reference_cache'));
    assert(count_exact(R,'ENABLE_PROCESS_REPLAN_WORKER = true;')==1);
    assert(contains(R,'activation_time=double(t_now)+double(obj.prediction_dt);'));
    assert(contains(R,'obj.poll_process_replan_worker(time.t,active,need_replan);'));
    assert(contains(R,'WORKER_PACKET_SENSOR_MEMORY_STALE'));
    assert(contains(R,'WORKER_PACKET_DEPENDENCY_STALE'));
    assert(contains(R,'WORKER_PACKET_OBSTACLE_MAP_STALE'));
    assert(contains(R,'The generator receives ONLY sensor-known obstacles:'));
    assert(contains(R,'''detected_only_obstacle_contract'',true'));
    assert(contains(R,'Initial known set is empty.'));
    assert(contains(R,'raw_sensor_gate alone may admit a previously unknown obstacle.'));
    assert(contains(R,'RAW=af7r36_single_core_mex(1,pkt);'));
    assert(contains(R,'obj.evaluate_reference_only_proposal_certificate(candidate)'));
    assert(contains(H,'WOBJ.invoke_replan_generator_shadow( ...'));
    assert(contains(H,'AF7R58ZZT_COMMIT_READY_V1'));
    assert(contains(H,'apply_source_authority(WOBJ,payload.source_authority);'));

    % Entire class parse under temporary alternate class name.
    parseDir=fullfile(outdir,'PARSE');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZZT_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(R,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    assert(~strcmp(parseText,R),'[AF7R58ZZT] class rename failed.');
    parsePath=fullfile(parseDir,[parseName '.m']);
    write_utf8(parsePath,parseText);
    addpath(parseDir,'-begin');
    cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZZT] patched class parse failed.');
    eval(['clear ' parseName]);

    % Helper parse.
    addpath(stageDir,'-begin');
    ch=onCleanup(@()safe_rmpath(stageDir)); %#ok<NASGU>
    clear af7r58zzt_process_worker
    nargin('af7r58zzt_process_worker');

    say(fid,'');
    say(fid,'[A. PREFLIGHT]');
    say(fid,' exact PRE SHA                        = 1 | %s',pre);
    say(fid,' exact staged POST SHA                = 1 | %s',POST_SHA);
    say(fid,' exact helper SHA                     = 1 | %s',HELPER_SHA);
    say(fid,' fixed collision horizon H=4 s        = 1');
    say(fid,' extended preview                     = 0');
    say(fid,' earliest activation                  = t + dt');
    say(fid,' Flight worker wait/block             = 0');
    say(fid,' stale sensor/dependency/map reject   = 1');
    say(fid,' generator/certificate math changed   = 0');
    say(fid,' full patched class parse             = 1');
    say(fid,' helper parse                         = 1');
    say(fid,' production writes                    = 0');

    % Transactional install.
    copyfile(pR,backupR,'f');
    if isfile(pH), copyfile(pH,backupH,'f'); end

    writeR=true;
    copyfile(stagedR,pR,'f');
    OUT.production_modified=true;

    writeH=true;
    copyfile(stagedH,pH,'f');
    OUT.helper_modified=true;

    post=file_hash(pR);
    hsha=file_hash(pH);
    OUT.post_sha=post;
    OUT.helper_sha=hsha;
    assert(strcmp(post,POST_SHA),'[AF7R58ZZT] production POST SHA mismatch.');
    assert(strcmp(hsha,HELPER_SHA),'[AF7R58ZZT] installed helper SHA mismatch.');

    OUT.status='PROCESS_WORKER_W1_INSTALLED__CLEAN_RERUN_REQUIRED';

    say(fid,'');
    say(fid,'[B. INSTALL]');
    say(fid,' REPLANNING_SYSTEM post SHA = %s',post);
    say(fid,' process-worker helper SHA   = %s',hsha);
    say(fid,' production modified         = 1');
    say(fid,' rollback performed          = 0');
    say(fid,' status = %s',OUT.status);

catch ME
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});
    try
        if writeR && isfile(backupR)
            copyfile(backupR,pR,'f');
        end
        if writeH
            if isfile(backupH)
                copyfile(backupH,pH,'f');
            elseif isfile(pH)
                delete(pH);
            end
        end
        OUT.rollback_performed=writeR||writeH;
        OUT.production_modified=false;
        OUT.helper_modified=false;
    catch
    end
    OUT.status='INSTALL_FAILED__ROLLBACK_ATTEMPTED';
    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier = %s',ME.identifier);
    say(fid,' message    = %s',ME.message);
    say(fid,' rollback   = %d',OUT.rollback_performed);
end

OUT.report_path=report;
OUT.mat_path=matp;
save(matp,'OUT','-v7');
assignin('base','AF7R58ZZT_OUT',OUT);
say(fid,'');
say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',matp);
say(fid,'status = %s',OUT.status);
end


function n=count_exact(s,pat)
n=numel(strfind(s,pat));
end

function s=read_utf8(path)
fid=fopen(path,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,'*uint8');
s=native2unicode(b.','UTF-8');
end

function write_utf8(path,s)
b=unicode2native(s,'UTF-8');
fid=fopen(path,'wb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,uint8(b),'uint8');
end

function h=file_hash(path)
md=java.security.MessageDigest.getInstance('SHA-256');
fid=fopen(path,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
while true
    b=fread(fid,1024*1024,'*uint8');
    if isempty(b), break; end
    md.update(b);
end
u=typecast(md.digest(),'uint8');
h=lower(reshape(dec2hex(u,2).',1,[]));
end

function say(fid,varargin)
fprintf(fid,[varargin{1} '\n'],varargin{2:end});
fprintf([varargin{1} '\n'],varargin{2:end});
end

function safe_rmpath(p)
try, rmpath(p); catch, end
end

function safe_fclose(fid)
try, fclose(fid); catch, end
end
